RANK = 1
SIG = True
SENSES = {'kernel': [('os core', ['system', 'driver', 'rebooted', 'panicked']), ('seed', ['corn', 'grain', 'plant', 'harvest']), ('math function', ['statistics', 'density', 'estimate'])]}  # term -> [(sense, definition_words)]
TEXT = "The kernel panicked and the system rebooted after the faulty driver loaded."
def lesk(term, context, senses):
    ctx = set(context.lower().split())
    best, bs = None, -1
    for sense, defwords in senses.get(term, []):
        overlap = len(ctx & set(defwords))
        if overlap > bs: best, bs = sense, overlap
    return best, bs
for term in SENSES:
    if term in TEXT.lower():
        sense, score = lesk(term, TEXT, SENSES)
        print("term '%s' -> sense: %s (overlap %d)" % (term, sense, score))
        if RANK >= 2:
            print("   candidates:", [s for s, _ in SENSES[term]])
if RANK >= 3:
    print("senses known:", sum(len(v) for v in SENSES.values()))
if SIG:
    print("Signature lineage stamp: JAH-SIG-TRM-" + "JAH-ATK177S-000001")
print("record:", "JAH-ATK177S-000001", "OK")

